package com.mockarena.identity.config;
import com.mockarena.identity.domain.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.*; import org.springframework.context.annotation.*; import org.springframework.core.env.Environment; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.*; import java.util.*;
@Configuration public class DevAdminBootstrap {
 @Bean ApplicationRunner devAdmin(IdentityUserRepository users,PasswordEncoder passwords,Environment env,@Value("${identity.dev.admin-bootstrap.enabled:false}") boolean enabled,@Value("${identity.dev.admin-bootstrap.email:}") String email,@Value("${identity.dev.admin-bootstrap.password:}") String password){return args->{if(!enabled||!env.matchesProfiles("dev"))return;if(email.isBlank()||password.isBlank())throw new IllegalStateException("Dev admin bootstrap requires email and password");String canonical=email.trim().toLowerCase(Locale.ROOT);if(users.findByEmail(canonical).isEmpty()){IdentityUser user=new IdentityUser(UUID.randomUUID(),canonical,"Development Admin",passwords.encode(password),Instant.now());user.grant(UserRole.ADMIN,Instant.now());users.save(user);}};}
}
